00010     Shader::Shader(const char* vertexPath, const char* fragmentPath)
00011     {
00012         //glfwMakeContextCurrent(PAIN::RenderStup::Windowvar);
00013 
00014         // 1. retrieve the vertex/fragment source code from filePath
00015         std::string vertexCode;
00016         std::string fragmentCode;
00017         std::ifstream vShaderFile;
00018         std::ifstream fShaderFile;
00019         // ensure ifstream objects can throw exceptions:
00020         vShaderFile.exceptions(std::ifstream::failbit | std::ifstream::badbit);
00021         fShaderFile.exceptions(std::ifstream::failbit | std::ifstream::badbit);
00022         try
00023         {
00024             // open files
00025             vShaderFile.open(vertexPath);
00026             fShaderFile.open(fragmentPath);
00027             std::stringstream vShaderStream, fShaderStream;
00028             // read file's buffer contents into streams
00029             vShaderStream << vShaderFile.rdbuf();
00030             fShaderStream << fShaderFile.rdbuf();
00031             // close file handlers
00032             vShaderFile.close();
00033             fShaderFile.close();
00034             // convert stream into string
00035             vertexCode = vShaderStream.str();
00036             fragmentCode = fShaderStream.str();
00037         }
00038         catch (std::ifstream::failure& e)
00039         {
00040             std::cout << "ERROR::SHADER::FILE_NOT_SUCCESSFULLY_READ: " << e.what() << std::endl;
00041         }
00042         const char* vShaderCode = vertexCode.c_str();
00043         const char* fShaderCode = fragmentCode.c_str();
00044         // 2. compile shaders
00045         unsigned int vertex, fragment;
00046         // vertex shader
00047         vertex = glCreateShader(GL_VERTEX_SHADER);
00048         glShaderSource(vertex, 1, &vShaderCode, NULL);
00049         glCompileShader(vertex);
00050         checkCompileErrors(vertex, "VERTEX");
00051         // fragment Shader
00052         fragment = glCreateShader(GL_FRAGMENT_SHADER);
00053         glShaderSource(fragment, 1, &fShaderCode, NULL);
00054         glCompileShader(fragment);
00055         checkCompileErrors(fragment, "FRAGMENT");
00056         // shader Program
00057         ID = glCreateProgram();
00058         glAttachShader(ID, vertex);
00059         glAttachShader(ID, fragment);
00060         glLinkProgram(ID);
00061         checkCompileErrors(ID, "PROGRAM");
00062         // delete the shaders as they're linked into our program now and no longer necessary
00063         glDeleteShader(vertex);
00064         glDeleteShader(fragment);
00065         //glfwMakeContextCurrent(NULL);
00066     }
