00095     Shader::Shader(VertexShader vertexshader, FragmentShader frgmentshader, GeometryShader geometryshader)
00096     {
00097         const char* vShaderCode = vertexshader.ShaderCode.c_str();
00098         const char* fShaderCode = frgmentshader.ShaderCode.c_str();
00099         const char* gshderCode = geometryshader.ShaderCode.c_str();
00100         // 2. compile shaders
00101         unsigned int vertex, fragment, geometry;
00102         // vertex shader
00103         vertex = glCreateShader(GL_VERTEX_SHADER);
00104         glShaderSource(vertex, 1, &vShaderCode, NULL);
00105         glCompileShader(vertex);
00106         checkCompileErrors(vertex, "VERTEX");
00107         // fragment Shader
00108         fragment = glCreateShader(GL_FRAGMENT_SHADER);
00109         glShaderSource(fragment, 1, &fShaderCode, NULL);
00110         glCompileShader(fragment);
00111         checkCompileErrors(fragment, "FRAGMENT");
00112         //geometry Shder
00113         geometry = glCreateShader(GL_GEOMETRY_SHADER);
00114         glShaderSource(geometry, 1, &gshderCode, NULL);
00115         glCompileShader(geometry);
00116         checkCompileErrors(geometry, "GEOMETRY");
00117         // shader Program
00118         ID = glCreateProgram();
00119         glAttachShader(ID, vertex);
00120         glAttachShader(ID, fragment);
00121         glAttachShader(ID, geometry);
00122         glLinkProgram(ID);
00123         checkCompileErrors(ID, "PROGRAM");
00124         // delete the shaders as they're linked into our program now and no longer necessary
00125         glDeleteShader(vertex);
00126         glDeleteShader(fragment);
00127         glDeleteShader(geometry);
00128     }
