00222     // ------------------------------------------------------------------------
00223 
00224     void Shader::checkCompileErrors(GLuint shader, std::string type)
00225     {
00226         GLint success;
00227         GLchar infoLog[1024];
00228         if (type != "PROGRAM")
00229         {
00230             glGetShaderiv(shader, GL_COMPILE_STATUS, &success);
00231             if (!success)
00232             {
00233                 glGetShaderInfoLog(shader, 1024, NULL, infoLog);
00234                 std::cout << "ERROR::SHADER_COMPILATION_ERROR of type: " << type << "\n" << infoLog << "\n -- --------------------------------------------------- -- " << std::endl;
00235             }
00236         }
00237         else
00238         {
00239             glGetProgramiv(shader, GL_LINK_STATUS, &success);
00240             if (!success)
00241             {
00242                 glGetProgramInfoLog(shader, 1024, NULL, infoLog);
00243                 std::cout << "ERROR::PROGRAM_LINKING_ERROR of type: " << type << "\n" << infoLog << "\n -- --------------------------------------------------- -- " << std::endl;
00244             }
00245         }
00246     }
