00274     ShaderU::ShaderU(char* vertexPath, char* fragmentPath) {
00275         std::string vertexCode;
00276         std::string fragmentCode;
00277         std::ifstream vShaderFile;
00278         std::ifstream fShaderFile;
00279         vShaderFile.open(vertexPath);
00280         fShaderFile.open(fragmentPath);
00281         std::stringstream vShaderStream, fShaderStream;
00282 
00283         if (vShaderFile.good() && fShaderFile.good()) {
00284             vShaderStream << vShaderFile.rdbuf();
00285             fShaderStream << fShaderFile.rdbuf();
00286             vShaderFile.close();
00287             fShaderFile.close();
00288             vertexCode = vShaderStream.str();
00289             fragmentCode = fShaderStream.str();
00290             const char* vShaderCode = vertexCode.c_str();
00291             const char* fShaderCode = fragmentCode.c_str();
00292             textcount = fShaderCode[2];
00293             unsigned int vertex, fragment;
00294             vertex = glCreateShader(GL_VERTEX_SHADER);
00295             glShaderSource(vertex, 1, &vShaderCode, NULL);
00296             glCompileShader(vertex);
00297             checkCompileErrors(vertex, "VERTEX");
00298             fragment = glCreateShader(GL_FRAGMENT_SHADER);
00299             glShaderSource(fragment, 1, &fShaderCode, NULL);
00300             glCompileShader(fragment);
00301             checkCompileErrors(fragment, "FRAGMENT");
00302             ID = glCreateProgram();
00303             glAttachShader(ID, vertex);
00304             glAttachShader(ID, fragment);
00305             glLinkProgram(ID);
00306             checkCompileErrors(ID, "PROGRAM");
00307             glDeleteShader(vertex);
00308             glDeleteShader(fragment);
00309 
00310         }
00311 
00312     }
